import { computed,onBeforeUnmount,onMounted,reactive,ref } from 'vue'
import { useRouter } from 'vue-router';import MasonicSeal from '@/shared/MasonicSeal.vue';import { useAuthStore } from '@/stores/authStore';import { useAccessStore } from '@/stores/accessStore';import { useRoomStore } from '@/stores/roomStore'
import { DEGREE_LABELS,isOpenKnowledgeBank,MASONIC_RITES,RITE_SHORT_LABELS } from '@/modules/questions/questionRules';import { RITE_GAME_CONFIG,requiresAccessExam } from '@/modules/game/access/riteAccess';import type { RoomLevel } from '@/modules/game/access/riteAccess';import type { BoardRoom } from '@/modules/game/lobby/types';import type { MasonicRite } from '@/modules/questions/types'
const router=useRouter(),authStore=useAuthStore(),accessStore=useAccessStore(),roomStore=useRoomStore();const showCreate=ref(false),filterRite=ref<MasonicRite|''>('');const masonicRites=MASONIC_RITES.filter(r=>r.masonic&&r.value!=='otro'),playableRites=MASONIC_RITES.filter(r=>r.value!=='otro');const preferredRite=computed(()=>accessStore.preferredRite??'reaa');const degreeLabel=computed(()=>authStore.masonicDegree?DEGREE_LABELS[authStore.masonicDegree]:'Sin grado');const newRoom=reactive<{name:string;rite:MasonicRite;level:RoomLevel;maxPlayers:number}>({name:'',rite:'reaa',level:authStore.masonicDegree??'aprendiz',maxPlayers:4});const roomConfig=computed(()=>RITE_GAME_CONFIG[newRoom.rite]);const filteredRooms=computed(()=>roomStore.openRooms.filter(room=>!filterRite.value||room.rite===filterRite.value))
onMounted(async()=>{if(authStore.currentUser)await accessStore.loadForUser(authStore.currentUser.uid);roomStore.watchRooms()});onBeforeUnmount(()=>roomStore.stop());const syncRoomConfig=()=>{newRoom.level=isOpenKnowledgeBank(newRoom.rite)?'general':(authStore.masonicDegree??'aprendiz')};const shortRite=(rite:MasonicRite)=>RITE_SHORT_LABELS[rite];const levelLabel=(level:RoomLevel)=>level==='general'?'General':DEGREE_LABELS[level];const isMember=(room:BoardRoom)=>Boolean(authStore.currentUser&&room.playerIds.includes(authStore.currentUser.uid));const needsExam=(room:BoardRoom)=>requiresAccessExam(preferredRite.value,authStore.masonicDegree,room.rite,room.level,accessStore.certificationFor(room.rite))
const setPreferredRite=async(event:Event)=>{if(authStore.currentUser)await accessStore.setPreferredRite(authStore.currentUser.uid,(event.target as HTMLSelectElement).value as MasonicRite)}
const createRoom=async()=>{if(!authStore.currentUser||!authStore.profile)return;const id=await roomStore.createRoom({name:newRoom.name,hostUid:authStore.currentUser.uid,hostName:authStore.profile.name,hostDegree:authStore.masonicDegree,rite:newRoom.rite,level:isOpenKnowledgeBank(newRoom.rite)?'general':newRoom.level,boardSize:roomConfig.value.boardSize,maxPlayers:newRoom.maxPlayers});router.push(`/game/turns?room=${id}`)}
const enterRoom=async(room:BoardRoom)=>{if(!authStore.currentUser||!authStore.profile)return;if(isMember(room)){router.push(`/game/turns?room=${room.id}`);return}if(needsExam(room)){router.push({path:'/reteje',query:{rite:room.rite,level:room.level,room:room.id}});return}await roomStore.joinRoom(room.id,{uid:authStore.currentUser.uid,name:authStore.profile.name,degree:authStore.masonicDegree,position:0,score:0,joinedAt:Date.now()});router.push(`/game/turns?room=${room.id}`)};const logout=async()=>{await authStore.logOut();router.push('/')}
